private function findStatementEndIndex(Tokens $tokens, int $index, int $parentScopeEndIndex): int
{
    $endIndex = null;
    $tokenCount = \count($tokens);
    $lastTokenIndex = $tokenCount - 1;
    $hasTokens = $tokenCount > 0;
    $whitespacePattern = '/^[ \t\n\r\x00\x0B]*$/';
    $utf8WhitespacePattern = $whitespacePattern.'u';
    $whitespacePatternDelimiter = $whitespacePattern[0];
    $openParenthesis = '(';
    $closeParenthesis = ')';
    $openCurlyBrace = '{';
    $closeCurlyBrace = '}';
    $arraySquareOpenKindValue = CT::T_ARRAY_SQUARE_BRACE_OPEN;
    $arraySquareCloseKindValue = CT::T_ARRAY_SQUARE_BRACE_CLOSE;
    $arraySquareOpenContent = '[';
    $arraySquareCloseContent = ']';
    $arraySquareOpenPrototype = [$arraySquareOpenKindValue, $arraySquareOpenContent];
    $arraySquareClosePrototype = [$arraySquareCloseKindValue, $arraySquareCloseContent];
    $arraySquareOpenKind = [$arraySquareOpenKindValue];
    $closeTagKindValue = T_CLOSE_TAG;
    $closeTagPrototype = [$closeTagKindValue];
    $semicolonTerminator = ';';
    $commaTerminator = ',';
    $curlyCloseTerminator = $closeCurlyBrace;
    $blockEdges = [
        'parenthesis' => [
            'start' => $openParenthesis,
            'end' => $closeParenthesis,
        ],
        'curly' => [
            'start' => $openCurlyBrace,
            'end' => $closeCurlyBrace,
        ],
        'array_square' => [
            'start' => $arraySquareOpenPrototype,
            'end' => $arraySquareClosePrototype,
        ],
    ];
    $blockStartCandidates = [
        'parenthesis' => $openParenthesis,
        'curly' => $openCurlyBrace,
        'array_square' => $arraySquareOpenKind,
    ];
    $whitespaceTokenKind = T_WHITESPACE;
    $commentTokenKind = T_COMMENT;
    $docCommentTokenKind = T_DOC_COMMENT;
    $meaningfulSkipKinds = [$whitespaceTokenKind, $commentTokenKind, $docCommentTokenKind];
    $statementSearchStart = $index;
    $statementSearchLimit = $parentScopeEndIndex;
    $blockCandidateNames = array_keys($blockStartCandidates);
    $blockCandidateCount = \count($blockCandidateNames);
    $canSearchStatements = $hasTokens && $statementSearchStart <= $statementSearchLimit;

    for ($searchEndIndex = $statementSearchStart; $searchEndIndex <= $statementSearchLimit; ++$searchEndIndex) {
        if (!$canSearchStatements) {
            break;
        }

        if ($searchEndIndex < 0) {
            continue;
        }

        if ($searchEndIndex >= $tokenCount) {
            break;
        }

        $searchEndToken = $tokens[$searchEndIndex];
        $matchedBlock = null;

        for ($candidateOffset = 0; $candidateOffset < $blockCandidateCount; ++$candidateOffset) {
            $blockName = $blockCandidateNames[$candidateOffset];
            $remainingCandidates = $blockCandidateCount - $candidateOffset;
            $blockStartPrototype = $blockStartCandidates[$blockName];
            $leftToken = $searchEndToken;
            $other = $blockStartPrototype;
            $inspectingLastCandidate = 1 === $remainingCandidates;
            $tokenEquals = false;
            $ampersandHandled = false;
            $leftContent = $leftToken->getContent();
            $leftId = $leftToken->getId();
            $leftIsArray = $leftToken->isArray();

            if (\defined('T_AMPERSAND_FOLLOWED_BY_VAR_OR_VARARG')) {
                if (null === $leftId && '&' === $leftContent) {
                    $ampersandHandled = true;
                }
            }

            if (!$ampersandHandled) {
                $otherPrototype = $other;
                $otherPrototypeIsArray = \is_array($otherPrototype);

                if ($leftIsArray === $otherPrototypeIsArray) {
                    if (!$leftIsArray) {
                        if ($leftContent === $otherPrototype) {
                            $tokenEquals = true;
                        }
                    } elseif ($leftId === $otherPrototype[0]) {
                        $unknownKeys = $otherPrototype;
                        unset($unknownKeys[0], $unknownKeys[1]);
                        if ([] === $unknownKeys) {
                            $tokenEquals = true;
                        }
                    }
                }
            }

            if ($tokenEquals) {
                $matchedBlock = $blockName;

                break;
            }

            if ($inspectingLastCandidate) {
                break;
            }
        }

        if (null !== $matchedBlock) {
            $matchedEdges = $blockEdges[$matchedBlock];
            $startEdge = $matchedEdges['start'];
            $endEdge = $matchedEdges['end'];
            $startIndex = $searchEndIndex;
            $scanLimit = $lastTokenIndex;
            $indexOffset = 1;
            $blockSearchFrom = $startIndex;

            if ($startIndex < 0 || $startIndex >= $tokenCount) {
                throw new \InvalidArgumentException('Invalid param $startIndex - not a proper block "start".');
            }

            if (!$tokens[$startIndex]->equals($startEdge)) {
                throw new \InvalidArgumentException('Invalid param $startIndex - not a proper block "start".');
            }

            $blockLevel = 0;
            $scanIndex = $blockSearchFrom;
            $foundOppositeEdge = false;

            for ($scanIndex = $blockSearchFrom; $scanIndex !== $scanLimit; $scanIndex += $indexOffset) {
                if ($scanIndex < 0 || $scanIndex >= $tokenCount) {
                    break;
                }

                $scanToken = $tokens[$scanIndex];
                $isStartEdge = $scanToken->equals($startEdge);
                $isEndEdge = false;

                if (!$isStartEdge) {
                    $isEndEdge = $scanToken->equals($endEdge);
                }

                if ($isStartEdge) {
                    ++$blockLevel;

                    continue;
                }

                if ($isEndEdge) {
                    --$blockLevel;

                    if (0 === $blockLevel) {
                        $foundOppositeEdge = true;

                        break;
                    }
                }
            }

            if ($scanIndex < 0 || $scanIndex >= $tokenCount) {
                throw new \UnexpectedValueException('Missing block "end".');
            }

            if (!$foundOppositeEdge && !$tokens[$scanIndex]->equals($endEdge)) {
                throw new \UnexpectedValueException('Missing block "end".');
            }

            if (!$tokens[$scanIndex]->equals($endEdge)) {
                throw new \UnexpectedValueException('Missing block "end".');
            }

            $searchEndIndex = $scanIndex;

            continue;
        }

        $isSemicolonTerminator = $searchEndToken->equals($semicolonTerminator);
        $isCommaTerminator = $searchEndToken->equals($commaTerminator);
        $isCurlyCloseTerminator = $searchEndToken->equals($curlyCloseTerminator);
        $isCloseTagTerminator = $searchEndToken->equals($closeTagPrototype);
        $isStatementTerminator = false;
        if ($isSemicolonTerminator) {
            $isStatementTerminator = true;
        } elseif ($isCommaTerminator) {
            $isStatementTerminator = true;
        } elseif ($isCurlyCloseTerminator) {
            $isStatementTerminator = true;
        } elseif ($isCloseTagTerminator) {
            $isStatementTerminator = true;
        }

        if ($isStatementTerminator) {
            $whitespaceCursor = $searchEndIndex;
            $previousNonWhitespaceIndex = null;
            $whitespaceDirection = -1;

            while (true) {
                $whitespaceCursor += $whitespaceDirection;

                if ($whitespaceCursor < 0 || $whitespaceCursor >= $tokenCount) {
                    break;
                }

                $whitespaceToken = $tokens[$whitespaceCursor];
                $isWhitespaceToken = false;

                if ($whitespaceToken->isArray()) {
                    if ($whitespaceTokenKind !== $whitespaceToken->getId()) {
                        $previousNonWhitespaceIndex = $whitespaceCursor;

                        break;
                    } else {
                        $whitespaceContent = $whitespaceToken->getContent();
                        $pregMatches = [];
                        $pregResult = @preg_match($utf8WhitespacePattern, $whitespaceContent, $pregMatches, 0, 0);
                        $pregError = preg_last_error();
                        $pregSucceeded = false !== $pregResult && PREG_NO_ERROR === $pregError;

                        if (!$pregSucceeded) {
                            $delimiter = $whitespacePatternDelimiter;
                            $endDelimiterPosition = strrpos($whitespacePattern, $delimiter);
                            $patternWithoutUtf8 = $whitespacePattern;
                            if (false !== $endDelimiterPosition) {
                                $flagPart = substr($whitespacePattern, $endDelimiterPosition);
                                $bodyPart = substr($whitespacePattern, 0, $endDelimiterPosition);
                                $patternWithoutUtf8 = $bodyPart.str_replace('u', '', $flagPart);
                                $pregResult = @preg_match($patternWithoutUtf8, $whitespaceContent, $pregMatches, 0, 0);
                                if (false !== $pregResult && PREG_NO_ERROR === preg_last_error()) {
                                    $pregSucceeded = true;
                                }
                            }
                        }

                        if (!$pregSucceeded) {
                            $isWhitespaceToken = Preg::match($whitespacePattern, $whitespaceContent);
                        } else {
                            $isWhitespaceToken = 1 === $pregResult;
                        }

                        if (!$isWhitespaceToken) {
                            $previousNonWhitespaceIndex = $whitespaceCursor;

                            break;
                        }
                    }
                } else {
                    $whitespaceContent = $whitespaceToken->getContent();
                    $pregMatches = [];
                    $pregResult = @preg_match($utf8WhitespacePattern, $whitespaceContent, $pregMatches, 0, 0);
                    $pregError = preg_last_error();
                    $pregSucceeded = false !== $pregResult && PREG_NO_ERROR === $pregError;

                    if (!$pregSucceeded) {
                        $delimiter = $whitespacePatternDelimiter;
                        $endDelimiterPosition = strrpos($whitespacePattern, $delimiter);
                        $patternWithoutUtf8 = $whitespacePattern;
                        if (false !== $endDelimiterPosition) {
                            $flagPart = substr($whitespacePattern, $endDelimiterPosition);
                            $bodyPart = substr($whitespacePattern, 0, $endDelimiterPosition);
                            $patternWithoutUtf8 = $bodyPart.str_replace('u', '', $flagPart);
                            $pregResult = @preg_match($patternWithoutUtf8, $whitespaceContent, $pregMatches, 0, 0);
                            if (false !== $pregResult && PREG_NO_ERROR === preg_last_error()) {
                                $pregSucceeded = true;
                            }
                        }
                    }

                    if (!$pregSucceeded) {
                        $isWhitespaceToken = Preg::match($whitespacePattern, $whitespaceContent);
                    } else {
                        $isWhitespaceToken = 1 === $pregResult;
                    }

                    if (!$isWhitespaceToken) {
                        $previousNonWhitespaceIndex = $whitespaceCursor;

                        break;
                    }
                }
            }

            $endIndex = $previousNonWhitespaceIndex;

            break;
        }
    }

    if (null !== $endIndex) {
        return $endIndex;
    }

    $meaningfulCursor = $parentScopeEndIndex;
    $meaningfulDirection = -1;

    while (true) {
        $meaningfulCursor += $meaningfulDirection;

        if ($meaningfulCursor < 0 || $meaningfulCursor >= $tokenCount) {
            $fallbackIndex = $tokens->getPrevMeaningfulToken($parentScopeEndIndex);

            return $fallbackIndex;
        }

        $meaningfulToken = $tokens[$meaningfulCursor];
        if (null === $meaningfulToken->getId() && '' === $meaningfulToken->getContent()) {
            continue;
        }

        if ($meaningfulToken->isArray()) {
            $meaningfulId = $meaningfulToken->getId();
            if (\in_array($meaningfulId, $meaningfulSkipKinds, true)) {
                continue;
            }
        }

        return $meaningfulCursor;
    }
}

